	tests := []struct {
		name    string
		nIDLen  namespace.IDSize
		minNID  []byte
		maxNID  []byte
		hash    []byte
		wantErr bool
		errType error
	}{
		{ // valid node
			"valid node",
			2,
			[]byte{0, 0},
			[]byte{1, 1},
			[]byte{1, 2, 3, 4},
			false,
			nil,
		},
		{ // mismatched namespace size
			"invalid node: length",
			2,
			[]byte{0},
			[]byte{1},
			[]byte{0},
			true,
			ErrInvalidNodeLen,
		},
		{ // correct size node (should pass)
			"correct size node",
			2,
			[]byte{0, 0},
			[]byte{1, 1},
			[]byte{1, 2, 3, 4},
			false,
			nil,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			n := NewNmtHasher(sha256.New(), tt.nIDLen, false)
			err := n.ValidateNodeFormat(append(append(tt.minNID, tt.maxNID...), tt.hash...))
