// TestValidateNodeExactSize tests that ValidateNodeFormat correctly validates
// the exact size of non-leaf nodes which should be 2*namespace size + hash output size.
func TestValidateNodeExactSize(t *testing.T) {
	nsLen := namespace.IDSize(2)
	baseHasher := sha256.New()
	// Valid node size: 2*namespace_size + hash_output_size = 2*2 + 32 = 36 bytes
	validNodeSize := int(2*nsLen) + baseHasher.Size()

	tests := []struct {
		name    string
		node    []byte
		wantErr bool
	}{
		{
			name:    "valid node with correct size",
			node:    make([]byte, validNodeSize),
			wantErr: false,
		},
		{
			name:    "node too small",
			node:    make([]byte, validNodeSize-1),
			wantErr: true,
		},
		{
			name:    "node too large",
			node:    make([]byte, validNodeSize+1),
			wantErr: true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			hasher := NewNmtHasher(sha256.New(), nsLen, false)
			err := hasher.ValidateNodeFormat(tt.node)
			assert.Equal(t, tt.wantErr, err != nil)
		})
	}
}

